 for(let i=0;i<1800;i++){b.t+=1/30;if(i%15===0){t.CavalryRide.step(c,g,g.units);phases.add(g.ridePlan?.phase||'new-run');g.setRun(!g.rest)}for(const u of g.units)t.Actor.of(u).step(1/30,null);t.BattleControl.prototype.step.call(g,1/30);if(phases.has('exit')&&phases.has('recover'))break}
 info('phases '+[...phases].join(','));ok(phases.has('charge')&&phases.has('exit'),'actual mounted movement reaches a charge and peels away after contact');ok(phases.has('recover'),'the looping withdrawal reaches a recovery position');
 if(g.ridePlan?.phase==='recover'){const p=g.ridePlan;for(const u of g.units)u.sta=10;b.t=p.at+X.recover+1;t.CavalryRide.step(c,g,g.units);ok(g.ridePlan===p&&g.rest,'tired cavalry recovers instead of immediately charging again');for(const u of g.units){u.sta=100;u.x=p.points.at(-1).x+(u.sx||0);u.y=p.points.at(-1).y+(u.sy||0)}t.CavalryRide.step(c,g,g.units);ok(!g.ridePlan&&!g.rest,'formed and rested cavalry can begin the next run-up')}else{ok(false,'tired cavalry recovers instead of immediately charging again');ok(false,'formed and rested cavalry can begin the next run-up')}
 const C={x:400,y:400},E={x:550,y:400},v={x:1,y:0};const safe=t.CavalryRide.safe;try{t.CavalryRide.safe=(a,p)=>p.y<=400;const route=t.CavalryRide.route(c,C,E,v,true);ok(route&&route.side===-1,'a blocked flank chooses the other escape arc');t.CavalryRide.safe=()=>false;ok(t.CavalryRide.route(c,C,E,v,true)===null,'no escape arc is fabricated through blocked terrain')}finally{t.CavalryRide.safe=safe}
 g.ridePlan={phase:'recover'};g.aiReset();ok(!g.ridePlan,'handing a group back to the AI clears its old riding plan');ok(!ERR.length,'curved cavalry movement has no runtime errors');
